package com.nextaicommerce.platform.shopify;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.support.*;import com.nextaicommerce.platform.web.WorkspaceAccessRepository;import tools.jackson.databind.ObjectMapper;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class ShopifyCatalogJobsTest {
 final UUID tenant=new UUID(0,1),connection=new UUID(0,2),id=new UUID(0,3),run=new UUID(0,4);final JdbcTemplate jdbc=mock(JdbcTemplate.class);final TransactionTemplate tx=mock(TransactionTemplate.class);final WorkspaceAccessRepository access=mock(WorkspaceAccessRepository.class);final ShopifyCatalogRepository observations=mock(ShopifyCatalogRepository.class);final ShopifyCatalogJobs jobs=new ShopifyCatalogJobs(jdbc,tx,access,observations,true);final Map<String,Object> state=new LinkedHashMap<>();final ObjectMapper json=new ObjectMapper();ShopifyCatalogJobs.Job job;
 @BeforeEach void setup(){when(tx.execute(any())).thenAnswer(i->((TransactionCallback<?>)i.getArgument(0)).doInTransaction(mock(org.springframework.transaction.TransactionStatus.class)));doAnswer(i->{((java.util.function.Consumer<org.springframework.transaction.TransactionStatus>)i.getArgument(0)).accept(mock(org.springframework.transaction.TransactionStatus.class));return null;}).when(tx).executeWithoutResult(any());
  when(access.canOperateAccount(tenant,"operator")).thenReturn(true);var store=new WorkspaceAccessRepository.ConnectionView(connection,tenant,"Account","Store","SHOPIFY","unit.myshopify.com","unit.myshopify.com","","Shopify","ACTIVE",null,true);when(access.listAccountOptions("operator",false)).thenReturn(List.of(new WorkspaceAccessRepository.AccountOption(tenant,"Account","A",null,List.of(store))));
  state.putAll(Map.of("actor","operator","connectionRevision",Instant.EPOCH.toString(),"queryRevision",ShopifyCatalogClient.REVISION,"deadline",Instant.now().plusSeconds(300).toString(),"requests",0,"costReserved",0,"pageRetries",0,"seen",List.of(),"cursors",List.of()));state.put("overallDeadline",Instant.now().plusSeconds(3600).toString());state.put("windowRequests",0);state.put("windowCostReserved",0);state.put("windowStartSeen",0);job=new ShopifyCatalogJobs.Job(tenant,connection,id,run,"owner",1,state);
  when(jdbc.queryForList(anyString(),eq(UUID.class),any(Object[].class))).thenReturn(List.of(connection));when(jdbc.queryForList(anyString(),any(Object[].class))).thenAnswer(i->List.of(Map.of("cursor",json.writeValueAsString(state))));
 }
 @Test void reconnectOrPermissionRefreshCannotResumeOldConnectionBinding(){var now=Instant.parse("2026-10-26T12:00:00Z");state.put("deadline",now.plusSeconds(300).toString());state.put("overallDeadline",now.plusSeconds(3600).toString());assertThat(ShopifyCatalogJobs.resumable(state,Instant.EPOCH,now)).isTrue();assertThat(ShopifyCatalogJobs.resumable(state,Instant.EPOCH.plusSeconds(1),now)).isFalse();assertThat(ShopifyCatalogJobs.resumable(state,Instant.EPOCH,now.plusSeconds(3600))).isFalse();state.put("queryRevision","old");assertThat(ShopifyCatalogJobs.resumable(state,Instant.EPOCH,now)).isFalse();}
 @Test void boundedWindowRolloverPreservesCursorRunEvidenceAndCumulativeBudgets(){var now=Instant.parse("2026-10-26T12:00:00Z");state.put("deadline",now.plusSeconds(300).toString());state.put("overallDeadline",now.plusSeconds(3600).toString());state.put("after","page20");state.put("seen",java.util.stream.IntStream.range(0,200).mapToObj(i->"variant"+i).toList());state.put("requests",20);state.put("costReserved",20000);state.put("windowRequests",20);state.put("windowCostReserved",20000);ShopifyCatalogJobs.rollWindow(state,now,false);assertThat(state).containsEntry("after","page20").containsEntry("requests",20).containsEntry("costReserved",20000).containsEntry("windowRequests",0).containsEntry("windowCostReserved",0).containsEntry("windowStartSeen",200);assertThat((List<?>)state.get("seen")).hasSize(200);assertThat(state.get("overallDeadline")).isEqualTo(now.plusSeconds(3600).toString());}
 @Test void legacyPartialWindowCanContinueWithoutRefetchingPreviousPages(){var now=Instant.now();state.remove("overallDeadline");state.remove("windowRequests");state.remove("windowCostReserved");state.remove("windowStartSeen");state.put("after","saved-cursor");state.put("requests",20);state.put("costReserved",20000);var original=Instant.parse(state.get("deadline").toString());ShopifyCatalogJobs.rollWindow(state,now,true);assertThat(state).containsEntry("after","saved-cursor").containsEntry("requests",20).containsEntry("costReserved",20000).containsEntry("overallDeadline",original.plusSeconds(3300).toString());}
 @Test void serverPauseCanSpanWorkWindowsWithoutShorteningIt(){Instant pause=Instant.now().plusSeconds(400);jobs.retry(job,pause);verify(jdbc).update(contains("SET status='WAITING'"),eq(java.sql.Timestamp.from(pause)),anyString(),eq(tenant),eq(connection),eq(id));}
 @Test void reservePersistsWorstCaseBudgetBeforeNetwork(){jobs.reserve(job);verify(jdbc).update(contains("SET cursor="),argThat((String value)->value.contains("\"requests\":1")&&value.contains("\"costReserved\":1000")),eq(tenant),eq(connection),eq(id));verifyNoInteractions(observations);}
 @Test void expiredBudgetOrQueryRevisionNeverPublishes(){for(String field:List.of("overallDeadline","requests","queryRevision")){Object old=state.get(field);state.put(field,switch(field){case "overallDeadline"->Instant.EPOCH.toString();case "requests"->1000;default->"old-query";});assertThatThrownBy(()->jobs.reserve(job)).isInstanceOf(IllegalArgumentException.class);state.put(field,old);}verifyNoInteractions(observations);verify(jdbc,never()).update(contains("SET cursor="),any(Object[].class));}
 @Test void lostLeaseAndRevokedPermissionCannotPublishOrAdvance(){when(jdbc.queryForList(anyString(),any(Object[].class))).thenReturn(List.of());assertThatThrownBy(()->jobs.reserve(job)).isInstanceOf(ShopifyCatalogJobs.LostLease.class);when(access.canOperateAccount(tenant,"operator")).thenReturn(false);assertThatThrownBy(()->jobs.reserve(job)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);verifyNoInteractions(observations);}
 @Test void cursorCyclesAreRejectedBeforeSourcePublication(){state.put("cursors",List.of("cycle"));var page=new ShopifyCatalogClient.Page(List.of(),"cycle",true,10,1000,100);assertThatThrownBy(()->jobs.publish(job,"raw",page,"USD",()->{})).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("cursor");verifyNoInteractions(observations);}
 @Test void retryNeverShortensServerPauseAndExhaustionIsNotSuccess(){Instant pause=Instant.now().plusSeconds(120);jobs.retry(job,pause);verify(jdbc).update(contains("SET status='WAITING'"),eq(java.sql.Timestamp.from(pause)),anyString(),eq(tenant),eq(connection),eq(id));state.put("pageRetries",3);jobs.retry(job,pause);verify(jdbc).update(contains("SET status=?,records_processed"),eq("FAILED"),eq(0),anyString(),eq(tenant),eq(connection),eq(id));}
 @Test void cancellationUsesOnlyExactTenantConnectionAndJobType(){when(jdbc.queryForList(startsWith("UPDATE marketplace_sync_jobs"),eq(UUID.class),any(Object[].class))).thenReturn(List.of(run));jobs.cancel(tenant,connection,"operator");verify(jdbc).queryForList(contains("status='SKIPPED'"),eq(UUID.class),eq(tenant),eq(connection),eq(ShopifyCatalogJobs.TYPE));verifyNoInteractions(observations);}
 @Test void lastCheckUsesOnlyActualCompletionMetadata(){var completed=new ShopifyCatalogJobs.Status(id,"COMPLETED","Done",359,Instant.EPOCH,Instant.parse("2026-10-27T05:00:00Z"));assertThat(completed.statusLabel()).isEqualTo("Synced");assertThat(completed.lastCheckLabel()).isEqualTo("Last Shopify SKU check · 10/27/26 · 05:00 UTC");assertThat(new ShopifyCatalogJobs.Status(id,"RUNNING","Reading",10,Instant.EPOCH).lastCheckLabel()).isEqualTo("No completed Shopify SKU check");}
}
